insert into public.villages (slug, name, tagline, description, zip, lat, lng, image_url, fun_fact) values ('auburndale', 'Auburndale', 'Riverside walks and a quiet commuter-rail village green', 'Tucked along the Charles River in Newton’s west end, Auburndale pairs canoe-launch riverbank with a compact Lexington Street business strip. It is the jumping-off point for the Charles River Reservation paths and the Auburndale Cove beach area.', '02466', 42.3459, -71.249, 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Pony_Truss_Trail_and_the_Charles_River%2C_December_2025.jpg/1920px-Pony_Truss_Trail_and_the_Charles_River%2C_December_2025.jpg', 'Just across the Charles in neighboring Weston stands the 1889 Norumbega Tower, built to mark a since-debunked theory that Vikings settled the riverbank — it’s visible from the Auburndale side of the water.')
