insert into public.villages (slug, name, tagline, description, zip, lat, lng, image_url, fun_fact) values ('chestnut-hill', 'Chestnut Hill', 'Reservoir loops, Boston College, and upscale shopping', 'Chestnut Hill straddles the Newton–Brookline–Boston line, anchored by the Chestnut Hill Reservoir loop, Boston College’s Gothic campus, and The Street shopping district.', '02467', 42.3268, -71.1668, 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Chestnut_Hill_Reservoir.jpg/1920px-Chestnut_Hill_Reservoir.jpg', 'The 1.5-mile Reservoir path is one of Greater Boston’s most-run loops — and the water is still an emergency backup supply.')
