insert into public.villages (slug, name, tagline, description, zip, lat, lng, image_url, fun_fact) values ('newton-centre', 'Newton Centre', 'The dining-and-dessert heart of Newton', 'Newton Centre is the city’s busiest village center: two dozen restaurants and cafés within a few blocks, the Green Line D branch, Crystal Lake a short walk south, and the Newton Centre Green for summer concerts.', '02459', 42.3298, -71.1926, 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Beacon_and_Centre_St_intersection_Newton_Center_March_2025_1.jpg/1920px-Beacon_and_Centre_St_intersection_Newton_Center_March_2025_1.jpg', 'Crystal Lake was once called Baptist Pond and supplied commercial ice to Boston before refrigeration.')
