insert into public.villages (slug, name, tagline, description, zip, lat, lng, image_url, fun_fact) values ('newton-corner', 'Newton Corner', 'Newton’s oldest settlement, right at the Watertown line', 'The city’s first settled village, Newton Corner sits where the Mass Pike meets Watertown. Expect historic Farlow Park, a busy Washington Street corridor, and quick access to the Charles River paths.', '02458', 42.3556, -71.1875, 'https://upload.wikimedia.org/wikipedia/commons/7/7d/Washington_Street%2C_Newton_Corner_2006.jpg', 'Newton Corner was simply called "Newton" until the railroad arrived and every other village needed a name too.')
