insert into public.villages (slug, name, tagline, description, zip, lat, lng, image_url, fun_fact) values ('newton-highlands', 'Newton Highlands', 'Walkable village square with a theatre and a hidden gorge', 'Newton Highlands has a genuinely charming square — bakery, bookshop, theatre — plus trailheads into Hemlock Gorge and the Upper Falls greenway just south.', '02461', 42.3218, -71.2062, 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Lincoln_St%2C_Newton_Highlands_MA.jpg/1920px-Lincoln_St%2C_Newton_Highlands_MA.jpg', 'The Highlands square is a designated National Register historic district, largely built out between 1880 and 1920.')
