insert into public.villages (slug, name, tagline, description, zip, lat, lng, image_url, fun_fact) values ('newton-lower-falls', 'Newton Lower Falls', 'Mill-era riverbank on the Wellesley border', 'A small, leafy village on the Charles at the Wellesley line, Lower Falls kept its 19th-century paper-mill bones and now offers riverside trails and easy Route 16 access.', '02462', 42.3312, -71.2549, 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Charles_River%2C_Newton_Lower_Falls_MA.jpg/1920px-Charles_River%2C_Newton_Lower_Falls_MA.jpg', 'Paper mills here supplied newsprint to Boston papers for more than a century.')
