insert into public.villages (slug, name, tagline, description, zip, lat, lng, image_url, fun_fact) values ('newton-upper-falls', 'Newton Upper Falls', 'Echo Bridge, Hemlock Gorge, and industrial-chic charm', 'Upper Falls wraps around the Charles River gorge. Echo Bridge and Hemlock Gorge Reservation make it Newton’s most dramatic bit of landscape, and the old mill buildings now hold studios and restaurants.', '02464', 42.3143, -71.2196, 'https://upload.wikimedia.org/wikipedia/commons/b/b0/NewtonMA_NewtonUpperFalls.jpg', 'Stand under Echo Bridge’s stone arch and a shout comes back to you as many as fifteen times.')
