insert into public.villages (slug, name, tagline, description, zip, lat, lng, image_url, fun_fact) values ('newtonville', 'Newtonville', 'Everyday Newton: markets, farmstands, and neighborhood dining', 'Newtonville’s Walnut Street strip is where locals actually shop — grocers, bakeries, a farmers market, and a growing restaurant row, all beside the commuter rail stop.', '02460', 42.3512, -71.2078, 'https://upload.wikimedia.org/wikipedia/commons/9/9b/Masonic_Building%2C_2022%2C_Newtonville_MA.jpg', 'The Newtonville farmers market has run on Walnut Street for decades and is a Tuesday institution.')
