insert into public.villages (slug, name, tagline, description, zip, lat, lng, image_url, fun_fact) values ('nonantum', 'Nonantum', 'Italian-American "the Lake" — bakeries, feasts, and bocce', 'Known locally as "the Lake," Nonantum is Newton’s tight-knit Italian-American village: red-sauce restaurants, generational bakeries, and the July St. Mary of Carmen Festival.', '02458', 42.3603, -71.2013, 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Coletti-Magni_Park%2C_Nonantum_MA.jpg/1920px-Coletti-Magni_Park%2C_Nonantum_MA.jpg', 'Nonantum has its own local slang, "Lake Talk," with words traced to Italian and Romani roots.')
on conflict (slug) do update set name = excluded.name, tagline = excluded.tagline, description = excluded.description, zip = excluded.zip, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, fun_fact = excluded.fun_fact;
insert into public.villages (slug, name, tagline, description, zip, lat, lng, image_url, fun_fact) values ('oak-hill', 'Oak Hill', 'Wooded conservation land in Newton’s southern corner', 'Oak Hill is Newton’s greenest, quietest quarter — mid-century streets threaded with conservation land, the Nahanton Park canoe launch, and the Charles River’s southern bend.', '02459', 42.3018, -71.1898, 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Oak_Hill_Park_Newton_MA_July_2025_1.jpg/1920px-Oak_Hill_Park_Newton_MA_July_2025_1.jpg', 'Nahanton Park’s meadows are a birding hotspot — over 180 species have been logged there.')
on conflict (slug) do update set name = excluded.name, tagline = excluded.tagline, description = excluded.description, zip = excluded.zip, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, fun_fact = excluded.fun_fact;
insert into public.villages (slug, name, tagline, description, zip, lat, lng, image_url, fun_fact) values ('thompsonville', 'Thompsonville', 'Newton’s smallest village, hiding a working farm', 'Thompsonville is a pocket neighborhood between Newton Centre and Oak Hill, best known as the home of Newton Community Farm — the city’s last working farm.', '02459', 42.3126, -71.1972, '', 'Newton Community Farm has been continuously farmed since the 1700s and is now a nonprofit teaching farm.')
