insert into public.villages (slug, name, tagline, description, zip, lat, lng, image_url, fun_fact) values ('waban', 'Waban', 'Village-square calm with trailheads to the Aqueduct', 'Waban is a small, residential village with a one-block square, a Green Line stop, and direct access to the Cochituate Aqueduct trail and Angier’s woods.', '02468', 42.3268, -71.2306, 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/Beacon_St%2C_Waban_MA.jpg/1920px-Beacon_St%2C_Waban_MA.jpg', 'Waban is named for Waban, a Nipmuc leader who was among the first to hear John Eliot preach at Nonantum in 1646.')
