insert into public.villages (slug, name, tagline, description, zip, lat, lng, image_url, fun_fact) values ('west-newton', 'West Newton', 'Cinema, Hill architecture, and a real village main street', 'West Newton pairs a genuine main street — including the beloved West Newton Cinema — with the grand Victorians of West Newton Hill and easy Charles River access.', '02465', 42.3487, -71.2258, 'https://upload.wikimedia.org/wikipedia/commons/6/69/NewtonMA_WestNewtonVillageCenter.jpg', 'The West Newton Cinema opened in 1937 and was rescued by a community campaign — it is now community-owned.')
