insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('auburndale-cove-riverside-playground', 'Auburndale Cove & Riverside Playground', 'A gentle Charles River cove with a sandy edge, big shade trees and one of Newton’s best-loved playgrounds.', 'Auburndale Cove is the friendliest stretch of the Charles in Newton: a wide, slow bend of river with a small sandy beach area, picnic lawn and a shaded playground just up the bank. Parking is free and rarely full outside July weekends.

Bring a blanket for the lawn, walk the paved path along the water toward the Recreation Road boardwalk, or launch a paddleboard from the cove. Restrooms are seasonal, so plan accordingly with small kids.', 'auburndale', 'outdoors-parks', '1 Riverside Road, Auburndale, MA 02466', 42.3439, -71.245, 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Pony_Truss_Trail_and_the_Charles_River%2C_December_2025.jpg/1920px-Pony_Truss_Trail_and_the_Charles_River%2C_December_2025.jpg', 'free'::price_type, 0, null, false, null, null, null, null, null, ARRAY['playground', 'river', 'picnic', 'stroller-friendly']::text[], true, 4.7, 96, 120, 4)
