insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('chestnut-hill-reservoir-loop', 'Chestnut Hill Reservoir Loop', 'A flat 1.5-mile gravel loop around open water, with the Boston skyline on the far side.', 'The Reservoir loop is the definitive Chestnut Hill activity: a mile and a half of level crushed stone with water on one side and mature trees on the other. It draws runners at dawn, strollers midday, and a golden-hour crowd that is worth planning around.

The path connects to the Green Line B branch at Cleveland Circle, so you can arrive without a car. Dogs on leash are welcome; swimming is not.', 'chestnut-hill', 'outdoors-parks', 'Beacon Street at Chestnut Hill Driveway, Chestnut Hill, MA 02467', 42.3288, -71.1638, 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Chestnut_Hill_Reservoir.jpg/1920px-Chestnut_Hill_Reservoir.jpg', 'free'::price_type, 0, null, false, null, null, 'Daily, dawn to dusk', null, null, ARRAY['running', 'walking', 'sunset', 'dog-friendly', 'free']::text[], true, 4.8, 412, 668, 120)
