insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('the-street-chestnut-hill', 'The Street Chestnut Hill', 'An open-air shopping block with big-name retail, a cinema, and better-than-average patio dining.', 'The Street is where Chestnut Hill does an afternoon: a walkable outdoor block of clothing shops, home goods, a Showcase cinema, and a dozen restaurants with real outdoor seating.

It is unapologetically upscale, but the plaza is free to wander, there is a splash-and-play area for kids in summer, and parking is plentiful — a rarity in Newton.', 'chestnut-hill', 'shopping', '33 Boylston Street, Chestnut Hill, MA 02467', 42.3238, -71.1708, 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/The_Street%2C_Chestnut_Hill_MA.jpg/1920px-The_Street%2C_Chestnut_Hill_MA.jpg', 'varies'::price_type, null, null, false, null, null, 'Daily, 10am–8pm (restaurants later)', null, null, ARRAY['shopping', 'cinema', 'patio', 'rainy day']::text[], false, 4.4, 287, 805, 149)
