insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('boston-college-campus-walk-bapst-library', 'Boston College Campus Walk & Bapst Library', 'Collegiate Gothic towers, a hilltop reservoir view, and a reading room that looks like a cathedral.', 'You do not need to be a student to walk the BC campus. Start at the Linden Lane gates, take in Gasson Hall’s tower, and if the doors are open, step into Bapst Library’s Ford Tower reading room — stained glass, vaulted ceilings, absolute silence.

Campus is prettiest in mid-October when the quad turns. Football Saturdays are electric but crowded; go on a weekday morning for the quiet version.', 'chestnut-hill', 'arts-culture', '140 Commonwealth Avenue, Chestnut Hill, MA 02467', 42.3278, -71.1688, 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Boston_College_Adlersaeule_Gasson_Hall_NW_9355_20190426.jpg/1920px-Boston_College_Adlersaeule_Gasson_Hall_NW_9355_20190426.jpg', 'free'::price_type, 0, null, false, null, null, null, null, null, ARRAY['architecture', 'walking', 'fall foliage', 'free']::text[], false, 4.7, 168, 942, 178)
