insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('reservoir-sunset-run-club', 'Reservoir Sunset Run Club', 'A no-drop group run around the Reservoir every Thursday evening, all paces welcome.', 'A neighborhood-organized group run that meets at the Beacon Street gate and does two loops of the Reservoir — roughly three miles — with a pace group for everyone from 8-minute miles to a brisk walk.

No sign-up, no fee, no one gets left behind. Many people stay for a drink in Cleveland Circle afterward.', 'chestnut-hill', 'fitness', 'Beacon Street Gate, Chestnut Hill Reservoir, Chestnut Hill, MA 02467', 42.3298, -71.1648, 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Chestnut_Hill_Reservoir.jpg/1920px-Chestnut_Hill_Reservoir.jpg', 'free'::price_type, 0, null, true, '2026-10-29T22:30:00.000Z', '2026-10-30T00:00:00.000Z', 'Every Thursday, March–November', null, null, ARRAY['running', 'social', 'beginner friendly', 'free']::text[], false, 4.6, 64, 1079, 27)
