insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('chestnut-hill-farmers-market', 'Chestnut Hill Farmers Market', 'Massachusetts growers, prepared food, and live music in the plaza on Saturday mornings.', 'A compact but well-curated market: five or six farms, a bread baker, a cheesemonger, and rotating prepared-food vendors. Live acoustic music from around ten.

Come early for produce and late for the discounted end-of-day bread. SNAP/HIP accepted at the market tent.', 'chestnut-hill', 'food-drink', 'Boylston Street Plaza, Chestnut Hill, MA 02467', 42.3248, -71.1658, 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/The_Street%2C_Chestnut_Hill_MA.jpg/1920px-The_Street%2C_Chestnut_Hill_MA.jpg', 'varies'::price_type, null, null, true, '2026-10-31T13:00:00.000Z', '2026-10-31T17:00:00.000Z', 'Saturdays, June–October', null, null, ARRAY['farmers market', 'local', 'live music', 'family']::text[], false, 4.5, 132, 1216, 56)
