insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('crystal-lake-beach', 'Crystal Lake Beach', 'Newton’s only public swimming beach — spring-fed, lifeguarded, and a ten-minute walk from Newton Centre.', 'Crystal Lake is the city’s summer center of gravity. The bathhouse beach on Rogers Street has lifeguards, a roped swim area, a dock, and a grassy slope that fills with towels by noon on hot days.

Resident passes cover the season; day passes are available at the gate. Outside beach hours the perimeter path is open year-round and is a lovely twenty-minute loop, with ice-skating some winters when the ice is certified.', 'newton-centre', 'outdoors-parks', '10 Rogers Street, Newton Centre, MA 02459', 42.3258, -71.1916, 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Crystal_Lake%2C_Newton_Centre_MA.jpg/1920px-Crystal_Lake%2C_Newton_Centre_MA.jpg', 'paid'::price_type, 10, 10, false, null, null, 'Daily, mid-June through Labor Day, 10am–7pm', null, null, ARRAY['swimming', 'beach', 'summer', 'lifeguard', 'family']::text[], true, 4.6, 341, 1353, 85)
