insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('newton-centre-green-summer-concert', 'Newton Centre Green Summer Concert', 'Free Thursday-evening concerts on the triangle green — bring a blanket and dinner from the square.', 'The city puts a stage on the Newton Centre Green and programs eight weeks of free evening concerts: brass bands, blues, a swing night, and one reliably chaotic kids’ music show.

The smart move is to pick up dinner from one of the two dozen restaurants ringing the square and eat on the grass. Bring a low chair; the green fills in fast after 6:30.', 'newton-centre', 'seasonal-events', 'Centre Street at Beacon Street, Newton Centre, MA 02459', 42.3308, -71.1916, 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Beacon_and_Centre_St_intersection_Newton_Center_March_2025_1.jpg/1920px-Beacon_and_Centre_St_intersection_Newton_Center_March_2025_1.jpg', 'free'::price_type, 0, null, true, '2027-07-01T23:00:00.000Z', '2027-07-02T01:00:00.000Z', 'Thursdays, July–August', null, null, ARRAY['live music', 'free', 'family', 'outdoor', 'summer']::text[], true, 4.7, 189, 1490, 114)
