insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('dessert-crawl-newton-centre-square', 'Dessert Crawl: Newton Centre Square', 'Four dessert stops within three blocks — ice cream, gelato, French pastry and a late-night cookie.', 'Newton Centre has an improbable density of dessert. A workable route: gelato on Union Street, then a pastry counter on Langley, then ice cream on Beacon, and finish with something warm from the bakery near the T stop.

Budget about $8 per stop. Most places stay open until at least nine, later on weekends — this is Newton’s best answer to "what do we do after dinner."', 'newton-centre', 'food-drink', 'Union Street & Langley Road, Newton Centre, MA 02459', 42.3303, -71.1936, 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Beacon_and_Centre_St_intersection_Newton_Center_March_2025_1.jpg/1920px-Beacon_and_Centre_St_intersection_Newton_Center_March_2025_1.jpg', 'paid'::price_type, 8, 32, false, null, null, 'Daily, most shops until 9pm', null, null, ARRAY['dessert', 'ice cream', 'walkable', 'date night']::text[], false, 4.8, 226, 1627, 143)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('newton-free-library', 'Newton Free Library', 'One of the busiest public libraries in Massachusetts: huge children’s wing, museum passes, quiet study floors.', 'The main library on Homer Street is a genuine civic anchor — a soaring atrium, an enormous children’s room with a dedicated program space, a teen room, and an upper floor of near-silent study carrels.

Do not miss the museum pass program: free or steeply discounted admission to the MFA, the Museum of Science, the Aquarium and more, reservable online with a Newton card. There is also a small café and a gallery that rotates local artists monthly.', 'newton-centre', 'family-kids', '330 Homer Street, Newton Centre, MA 02459', 42.3328, -71.1946, 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/Newton_Free_Library_May_2026.jpg/1920px-Newton_Free_Library_May_2026.jpg', 'free'::price_type, 0, null, false, null, null, 'Mon–Thu 9am–9pm, Fri–Sat 9am–5pm, Sun 1pm–5pm', null, null, ARRAY['library', 'indoor', 'rainy day', 'museum passes', 'free']::text[], false, 4.9, 508, 1764, 172)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('trivia-night-in-the-square', 'Trivia Night in the Square', 'Tuesday-night pub trivia in Newton Centre — teams of up to six, no cover.', 'A long-running trivia night that draws a mix of grad students, teachers, and neighbors who have been playing on the same team for a decade. Six rounds, a music round, and a genuinely competitive final wager.

Arrive by 7:15 to get a table. No cover; a house tab prize for the winners. Kitchen runs late, which in Newton is worth noting.', 'newton-centre', 'nightlife', 'Union Street, Newton Centre, MA 02459', 42.3288, -71.1906, 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Beacon_and_Centre_St_intersection_Newton_Center_March_2025_1.jpg/1920px-Beacon_and_Centre_St_intersection_Newton_Center_March_2025_1.jpg', 'varies'::price_type, null, null, true, '2026-10-27T23:30:00.000Z', '2026-10-28T02:00:00.000Z', 'Every Tuesday, year-round', null, null, ARRAY['trivia', 'bar', 'social', '21+']::text[], false, 4.4, 91, 1901, 21)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('farlow-park', 'Farlow Park', 'A Victorian-era pocket park with a pond, weeping willows and Newton’s oldest planted landscape.', 'Farlow Park is a small 19th-century park with a duck pond, mature willows, and curving paths that were laid out when Newton Corner was the city’s fashionable address. It is an unexpectedly peaceful spot given how close the Mass Pike is.

Good for a twenty-minute walk, a bench lunch, or letting small kids run. The surrounding streets have some of the best-preserved Victorian houses in the city.', 'newton-corner', 'outdoors-parks', 'Church Street at Park Street, Newton Corner, MA 02458', 42.3546, -71.1855, 'https://upload.wikimedia.org/wikipedia/commons/1/14/NewtonMA_FarlowPark.jpg', 'free'::price_type, 0, null, false, null, null, null, null, null, ARRAY['pond', 'historic', 'quiet', 'stroller-friendly', 'free']::text[], false, 4.4, 67, 2038, 50)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('charles-river-greenway-newton-corner-access', 'Charles River Greenway — Newton Corner Access', 'Hop onto the paved riverside path here and ride all the way into Boston without a traffic light.', 'The access point near Nonantum Road puts you on the Charles River paths with a clean shot east toward Watertown Square, Cambridge and the Esplanade — roughly nine miles to the Museum of Science.

Mostly flat and fully paved, so it works for road bikes, joggers and rollerbladers alike. Heading west from here gets scrappier; go east.', 'newton-corner', 'fitness', 'Nonantum Road at Charles Street, Newton Corner, MA 02458', 42.3586, -71.1865, 'https://upload.wikimedia.org/wikipedia/commons/7/7d/Washington_Street%2C_Newton_Corner_2006.jpg', 'free'::price_type, 0, null, false, null, null, null, null, null, ARRAY['cycling', 'running', 'river', 'commute', 'free']::text[], false, 4.6, 143, 2175, 79)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('newton-corner-sunday-brunch-row', 'Newton Corner Sunday Brunch Row', 'Three brunch spots within a block of the Washington Street rotary, none of them requiring a reservation.', 'Newton Corner’s brunch scene is unglamorous and reliable: a diner-style counter, a bakery-café with excellent laminated pastry, and a full-service restaurant that does a proper eggs benedict.

Waits peak between 10:30 and noon on Sundays. Street parking is free but tight — the municipal lot behind Washington Street is the local secret.', 'newton-corner', 'food-drink', 'Washington Street, Newton Corner, MA 02458', 42.3561, -71.1885, 'https://upload.wikimedia.org/wikipedia/commons/7/7d/Washington_Street%2C_Newton_Corner_2006.jpg', 'paid'::price_type, 14, 28, false, null, null, 'Saturdays & Sundays, 8am–2pm', null, null, ARRAY['brunch', 'coffee', 'no reservation', 'family']::text[], false, 4.3, 118, 2312, 108)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('newton-history-walking-tour', 'Newton History Walking Tour', 'A 90-minute docent-led walk through the city’s first settled village and its Victorian streetscape.', 'Starting at Farlow Park, this volunteer-led walk covers Newton Corner’s arc from 1630s settlement to railroad suburb to highway casualty — including the blocks lost to the Mass Pike in the 1960s.

About a mile and a half at a conversational pace, with plenty of stops. Suggested donation supports the Newton History Museum at the Jackson Homestead.', 'newton-corner', 'arts-culture', 'Farlow Park, Church Street, Newton Corner, MA 02458', 42.3541, -71.185, 'https://upload.wikimedia.org/wikipedia/commons/1/14/NewtonMA_FarlowPark.jpg', 'paid'::price_type, 10, 10, true, '2027-05-08T18:00:00.000Z', '2027-05-08T19:30:00.000Z', 'Second Saturday of the month, May–October', null, null, ARRAY['history', 'walking tour', 'architecture', 'adults']::text[], false, 4.7, 52, 2449, 137)
