insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('newton-corner-playground-at-cabot', 'Newton Corner Playground at Cabot', 'Shaded modern play structures, a toddler section, and a splash pad in summer.', 'A well-maintained neighborhood playground with genuinely good shade — rare and valuable in August. Separate structures for under-5s and older kids, plus swings with two bucket seats and a summer splash pad.

Fenced on three sides, which parents of runners will appreciate. Adjacent ball fields and a basketball court for older siblings.', 'newton-corner', 'family-kids', '229 Cabot Street, Newton Corner, MA 02458', 42.3526, -71.1895, 'https://upload.wikimedia.org/wikipedia/commons/7/7d/Washington_Street%2C_Newton_Corner_2006.jpg', 'free'::price_type, 0, null, false, null, null, 'Daily, dawn to dusk; splash pad late June–August', null, null, ARRAY['playground', 'splash pad', 'shade', 'fenced', 'free']::text[], false, 4.5, 88, 186, 166)
