insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('newton-highlands-village-square-stroll', 'Newton Highlands Village Square Stroll', 'Two blocks of independent shops — bookseller, bakery, hardware store, florist — around the Green Line stop.', 'The Highlands square is what people mean when they say Newton has real village centers. Within two blocks: an independent bookshop, a bakery with a line on Saturday, an old-school hardware store, a florist, and a couple of good restaurants.

Park once and walk the whole thing in an hour. The D-branch stop puts you here from Downtown Crossing in about twenty-five minutes.', 'newton-highlands', 'shopping', 'Lincoln Street at Walnut Street, Newton Highlands, MA 02461', 42.3223, -71.2052, 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Lincoln_St%2C_Newton_Highlands_MA.jpg/1920px-Lincoln_St%2C_Newton_Highlands_MA.jpg', 'varies'::price_type, null, null, false, null, null, 'Most shops Mon–Sat 10am–6pm', null, null, ARRAY['independent shops', 'bookstore', 'walkable', 'T-accessible']::text[], true, 4.6, 154, 323, 15)
