insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('hemlock-gorge-reservation-echo-bridge', 'Hemlock Gorge Reservation & Echo Bridge', 'Hemlock-shaded trails above a rocky river gorge, with a stone aqueduct arch that echoes fifteen times.', 'Hemlock Gorge is Newton’s most dramatic landscape — the Charles narrows and drops through a rock cut, with old-growth hemlocks on the slopes above. Echo Bridge, an 1877 aqueduct arch, crosses the gorge, and a stairway leads down to a platform beneath it.

Stand on the platform and shout. The echo is genuinely startling and delights kids every time. Trails are short but rooty and steep in places; wear real shoes.', 'newton-highlands', 'outdoors-parks', 'Ellis Street, Newton Highlands, MA 02461', 42.3178, -71.2092, 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/A_closer_view_of_the_Echo_Bridge%2C_Sudbury_Aqueduct.jpg/1920px-A_closer_view_of_the_Echo_Bridge%2C_Sudbury_Aqueduct.jpg', 'free'::price_type, 0, null, false, null, null, null, null, null, ARRAY['hiking', 'echo bridge', 'gorge', 'hidden gem', 'free']::text[], true, 4.8, 276, 460, 44)
