insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('cold-spring-park-trails', 'Cold Spring Park Trails', '67 acres of woodland loop trails, a cross-country course, and a Tuesday farmers market in season.', 'Cold Spring Park is Newton’s workhorse open space: a flat two-mile network of wood-chip and gravel loops through mixed forest and wetland, popular with dog walkers, cross-country teams and stroller pushers.

The Beacon Street lot hosts the Newton Farmers Market on Tuesday afternoons in summer and fall. Boardwalks cross the wettest sections, but spring mud is real.', 'newton-highlands', 'outdoors-parks', '1200 Beacon Street, Newton Highlands, MA 02461', 42.3258, -71.2032, 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Lincoln_St%2C_Newton_Highlands_MA.jpg/1920px-Lincoln_St%2C_Newton_Highlands_MA.jpg', 'free'::price_type, 0, null, false, null, null, 'Daily, dawn to dusk', null, null, ARRAY['trails', 'dog-friendly', 'cross country', 'farmers market', 'free']::text[], false, 4.7, 231, 597, 73)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('community-theatre-night-in-the-highlands', 'Community Theatre Night in the Highlands', 'Local companies stage plays and musicals in a small Highlands house — tickets under $30.', 'Newton’s community theatre scene is more ambitious than you would expect: full musicals, Sondheim revivals, and new work by local playwrights, staged in an intimate house where no seat is far from the stage.

Runs are short — usually two weekends — so check dates and buy early. Street parking is free after 6pm.', 'newton-highlands', 'arts-culture', 'Lincoln Street, Newton Highlands, MA 02461', 42.3228, -71.2082, 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Lincoln_St%2C_Newton_Highlands_MA.jpg/1920px-Lincoln_St%2C_Newton_Highlands_MA.jpg', 'paid'::price_type, 18, 30, true, '2026-10-30T23:30:00.000Z', '2026-10-31T02:00:00.000Z', 'Select Fri–Sun through the season', null, null, ARRAY['theatre', 'live performance', 'date night']::text[], false, 4.5, 79, 734, 102)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('highlands-yoga-in-the-park', 'Highlands Yoga in the Park', 'Donation-based outdoor vinyasa on the Cold Spring Park lawn, Saturday mornings.', 'A local studio brings mats and a portable speaker to the Cold Spring Park lawn for an all-levels vinyasa class in the open air. Sixty minutes, gentle enough for beginners, with modifications called throughout.

Suggested $10 donation, nobody turned away. Cancelled for rain — check the studio’s socials by 7am.', 'newton-highlands', 'fitness', 'Cold Spring Park lawn, 1200 Beacon Street, Newton Highlands, MA 02461', 42.3263, -71.2037, 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Lincoln_St%2C_Newton_Highlands_MA.jpg/1920px-Lincoln_St%2C_Newton_Highlands_MA.jpg', 'varies'::price_type, null, null, true, '2027-06-05T12:30:00.000Z', '2027-06-05T13:30:00.000Z', 'Saturdays, June–September', null, null, ARRAY['yoga', 'outdoor', 'all levels', 'donation']::text[], false, 4.7, 68, 871, 131)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('charles-river-path-lower-falls-riverbank', 'Charles River Path — Lower Falls Riverbank', 'A short, pretty riverside walk past old mill dams where the Charles drops toward Wellesley.', 'Lower Falls earned its name from the drop in the river that once powered paper mills. The path along the bank gives you the dam, the old mill foundations, and a surprisingly loud stretch of moving water for suburban Boston.

It is a half-mile out and back rather than a hike. Combine it with the Blue Heron Bridge to cross into Wellesley for a longer loop.', 'newton-lower-falls', 'outdoors-parks', 'Concord Street at Washington Street, Newton Lower Falls, MA 02462', 42.3322, -71.2529, 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Charles_River%2C_Newton_Lower_Falls_MA.jpg/1920px-Charles_River%2C_Newton_Lower_Falls_MA.jpg', 'free'::price_type, 0, null, false, null, null, null, null, null, ARRAY['river', 'walking', 'history', 'quick stop', 'free']::text[], false, 4.4, 62, 1008, 160)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('blue-heron-bridge-crossing', 'Blue Heron Bridge Crossing', 'A pedestrian bridge over the Charles connecting Newton to Wellesley — great heron spotting at dusk.', 'This footbridge links the Lower Falls riverbank to the Wellesley side, opening up a two-mile loop that most Newton residents do not know exists. It is named for the great blue herons that stalk the shallows.

Best at dusk in late summer, when the herons are active and the light on the water is worth the trip on its own. Bring binoculars if you have them.', 'newton-lower-falls', 'outdoors-parks', 'Off Concord Street, Newton Lower Falls, MA 02462', 42.3302, -71.2519, 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Charles_River%2C_Newton_Lower_Falls_MA.jpg/1920px-Charles_River%2C_Newton_Lower_Falls_MA.jpg', 'free'::price_type, 0, null, false, null, null, null, null, null, ARRAY['birding', 'bridge', 'hidden gem', 'sunset', 'free']::text[], false, 4.6, 47, 1145, 9)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('lower-falls-coffee-pastry-stop', 'Lower Falls Coffee & Pastry Stop', 'A small café on the Route 16 corner — good espresso, better scones, six seats.', 'Tiny, competent, and exactly what the village needed: a proper espresso machine, house-baked scones and morning buns, and a couple of tables that turn over fast.

Mostly a takeaway stop for people heading to the river path or over to Wellesley. Sold out of pastry by eleven on weekends.', 'newton-lower-falls', 'food-drink', 'Washington Street, Newton Lower Falls, MA 02462', 42.3332, -71.2559, 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Charles_River%2C_Newton_Lower_Falls_MA.jpg/1920px-Charles_River%2C_Newton_Lower_Falls_MA.jpg', 'paid'::price_type, 4, 14, false, null, null, 'Mon–Fri 7am–3pm, Sat–Sun 8am–2pm', null, null, ARRAY['coffee', 'bakery', 'takeaway', 'quick stop']::text[], false, 4.6, 104, 1282, 38)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('mill-village-architecture-walk', 'Mill Village Architecture Walk', 'A self-guided loop past 19th-century mill housing, a 1811 church, and the old paper works.', 'Lower Falls is unusually intact for a New England mill village: worker housing, the mill owner’s house, and St. Mary’s church all still stand within a few blocks of the dam that started it all.

Download the self-guided map from the Newton History Museum site, or just wander — the interpretive signs along Concord Street cover the essentials. About forty-five minutes.', 'newton-lower-falls', 'arts-culture', 'Concord Street, Newton Lower Falls, MA 02462', 42.3327, -71.2574, 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Lower_Falls_Wine_Company%2C_Newton_Lower_Falls_MA.jpg/1920px-Lower_Falls_Wine_Company%2C_Newton_Lower_Falls_MA.jpg', 'free'::price_type, 0, null, false, null, null, null, null, null, ARRAY['self-guided', 'history', 'architecture', 'free']::text[], false, 4.2, 33, 1419, 67)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('lower-falls-playground-ball-field', 'Lower Falls Playground & Ball Field', 'A quiet neighborhood playground that never feels crowded, with a full ball field beside it.', 'Because Lower Falls is Newton’s smallest-feeling village, its playground is the one you go to when everywhere else is packed. Standard modern equipment, good swings, and a bench line with actual shade.

The adjacent field hosts little-league practices on weekday evenings. Parking is easy, which cannot be said of most Newton playgrounds.', 'newton-lower-falls', 'family-kids', 'Hagar Street, Newton Lower Falls, MA 02462', 42.3292, -71.2569, 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Charles_River%2C_Newton_Lower_Falls_MA.jpg/1920px-Charles_River%2C_Newton_Lower_Falls_MA.jpg', 'free'::price_type, 0, null, false, null, null, 'Daily, dawn to dusk', null, null, ARRAY['playground', 'uncrowded', 'ball field', 'free']::text[], false, 4.4, 39, 1556, 96)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('echo-bridge-photo-walk', 'Echo Bridge Photo Walk', 'The classic Newton shot: a stone arch over a gorge, best in the last hour of light in October.', 'From the Upper Falls side, a short trail brings you to the viewpoint that puts Echo Bridge’s full 130-foot arch in frame with the river below. In mid-October the hemlocks and maples turn the whole gorge gold.

Go an hour before sunset. The descent to the under-bridge platform is steep and slick when wet — worth it, but take care with kids.', 'newton-upper-falls', 'arts-culture', 'Chestnut Street at Ellis Street, Newton Upper Falls, MA 02464', 42.3163, -71.2166, 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/A_closer_view_of_the_Echo_Bridge%2C_Sudbury_Aqueduct.jpg/1920px-A_closer_view_of_the_Echo_Bridge%2C_Sudbury_Aqueduct.jpg', 'free'::price_type, 0, null, false, null, null, null, null, null, ARRAY['photography', 'fall foliage', 'echo bridge', 'free']::text[], true, 4.8, 197, 1693, 125)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('upper-falls-greenway', 'Upper Falls Greenway', 'A flat, paved rail-trail through the old mill district, with public art and a mile of easy walking.', 'Built on an abandoned rail bed, the Greenway runs about a mile from Needham Street through the heart of the old industrial village, with murals, benches and interpretive signs along the way.

Fully paved and level, so it works for wheelchairs, strollers and scooters. Connects toward Hemlock Gorge at the north end for a longer outing.', 'newton-upper-falls', 'fitness', 'Needham Street at Oak Street, Newton Upper Falls, MA 02464', 42.3123, -71.2206, 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Upper_Falls_Greenway%2C_Newton_Upper_Falls_MA.jpg/1920px-Upper_Falls_Greenway%2C_Newton_Upper_Falls_MA.jpg', 'free'::price_type, 0, null, false, null, null, 'Daily, dawn to dusk', null, null, ARRAY['rail trail', 'accessible', 'public art', 'walking', 'free']::text[], false, 4.6, 158, 1830, 154)
