insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('nahanton-park', 'Nahanton Park', 'Meadows, woods and a canoe launch on the Charles — Newton’s premier birding spot at 180+ species.', 'Nahanton Park’s mix of meadow, wetland and riverbank makes it the most biologically interesting open space in Newton. Birders have logged well over 180 species; spring migration in the meadow edges is genuinely excellent.

A canoe and kayak launch sits at the river end, and the community gardens occupy the upper field. Trails are easy but unpaved. Winter Street lot is the closest parking.', 'oak-hill', 'outdoors-parks', '455 Nahanton Street, Oak Hill, MA 02459', 42.3038, -71.1878, 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Oak_Hill_Park_Newton_MA_July_2025_1.jpg/1920px-Oak_Hill_Park_Newton_MA_July_2025_1.jpg', 'free'::price_type, 0, null, false, null, null, 'Daily, dawn to dusk', null, null, ARRAY['birding', 'canoe launch', 'meadow', 'trails', 'free']::text[], true, 4.8, 164, 1348, 20)
