insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('oak-hill-conservation-trails', 'Oak Hill Conservation Trails', 'Quiet, rooty single-track through Newton’s biggest stretch of unbroken woodland.', 'A network of narrow footpaths threads the conservation land in Newton’s southern corner. It is the closest thing the city has to a real forest walk — hemlock, oak, glacial boulders, and almost no one else.

Signage is sparse; download a map or drop a pin at your car. Ticks are a genuine consideration from May through September.', 'oak-hill', 'outdoors-parks', 'Saw Mill Brook Parkway, Oak Hill, MA 02459', 42.2988, -71.1918, 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Oak_Hill_Park_Newton_MA_July_2025_1.jpg/1920px-Oak_Hill_Park_Newton_MA_July_2025_1.jpg', 'free'::price_type, 0, null, false, null, null, null, null, null, ARRAY['hiking', 'woods', 'solitude', 'hidden gem', 'free']::text[], false, 4.5, 72, 1485, 49)
