insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('nahanton-park-community-gardens', 'Nahanton Park Community Gardens', 'Over a hundred garden plots on a sunny hillside — open to walk through, with a waitlist to grow.', 'The community gardens are a lovely thing to walk through in August, when the plots are at full tilt: tomato jungles, sunflower walls, and gardeners happy to talk about what is working.

Plots are city-managed with an annual fee and a real waitlist, but the paths are public. Great low-key outing with kids who like seeing where food comes from.', 'oak-hill', 'family-kids', 'Nahanton Street, Oak Hill, MA 02459', 42.3043, -71.1883, 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Oak_Hill_Park_Newton_MA_July_2025_1.jpg/1920px-Oak_Hill_Park_Newton_MA_July_2025_1.jpg', 'varies'::price_type, null, null, false, null, null, 'Daylight hours, April–November', null, null, ARRAY['gardens', 'kids', 'walkthrough', 'free']::text[], false, 4.6, 55, 1622, 78)
