insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('charles-river-canoe-launch-at-nahanton', 'Charles River Canoe Launch at Nahanton', 'Put in on the Charles’s quiet southern bend — no motorboats, no crowds, herons everywhere.', 'This launch gives you the slowest, quietest water on the Newton stretch of the Charles. Paddle upstream toward Needham through marsh and overhanging trees and you will see more wildlife than people.

Bring your own boat — this is a launch, not a rental. Small gravel lot; get there before nine on summer weekends.', 'oak-hill', 'fitness', 'Nahanton Street launch, Oak Hill, MA 02459', 42.3033, -71.1873, 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Oak_Hill_Park_Newton_MA_July_2025_1.jpg/1920px-Oak_Hill_Park_Newton_MA_July_2025_1.jpg', 'free'::price_type, 0, null, false, null, null, null, null, null, ARRAY['kayak', 'canoe', 'wildlife', 'quiet water', 'free']::text[], false, 4.7, 61, 1759, 107)
