insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('oak-hill-winter-sledding-hill', 'Oak Hill Winter Sledding Hill', 'A long, open slope that becomes the neighborhood sledding destination after every storm.', 'When Newton gets six inches, this is where Oak Hill goes. A long, wide, obstacle-free slope with a gentle side for little kids and a steeper line for the committed.

No lights, so daylight only. Street parking fills fast the morning after a storm — walk in if you can.', 'oak-hill', 'seasonal-events', 'Brookline Street at Saw Mill Brook Parkway, Oak Hill, MA 02459', 42.2993, -71.1913, 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Oak_Hill_Park_Newton_MA_July_2025_1.jpg/1920px-Oak_Hill_Park_Newton_MA_July_2025_1.jpg', 'free'::price_type, 0, null, false, null, null, 'After snowfall, December–March', null, null, ARRAY['sledding', 'winter', 'family', 'free']::text[], false, 4.6, 94, 1896, 136)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, description = excluded.description, village_slug = excluded.village_slug, category_slug = excluded.category_slug, address = excluded.address, lat = excluded.lat, lng = excluded.lng, image_url = excluded.image_url, price_type = excluded.price_type, price_min = excluded.price_min, price_max = excluded.price_max, is_event = excluded.is_event, start_at = excluded.start_at, end_at = excluded.end_at, recurrence = excluded.recurrence, website = excluded.website, phone = excluded.phone, tags = excluded.tags, featured = excluded.featured, rating_avg = excluded.rating_avg, rating_count = excluded.rating_count, view_count = excluded.view_count, save_count = excluded.save_count;
insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('newton-community-farm', 'Newton Community Farm', 'The city’s last working farm — a farmstand, kids’ programs, and 300 years of continuous cultivation.', 'Newton Community Farm sits on the last piece of continuously farmed land in the city, now run as a nonprofit teaching farm. There are laying hens, raised beds, a greenhouse, and a farmstand that opens in the afternoon with what was picked that morning.

The education programs — summer camp, preschool farm mornings, adult workshops on seed starting and beekeeping — are the real draw and do sell out. Walking the grounds is free.', 'thompsonville', 'family-kids', '303 Nahanton Street, Thompsonville, MA 02459', 42.3136, -71.1962, '', 'varies'::price_type, null, null, false, null, null, 'Farmstand Tue–Sat afternoons, June–October', 'https://newtoncommunityfarm.org', null, ARRAY['farm', 'kids', 'CSA', 'workshops', 'hidden gem']::text[], true, 4.9, 187, 2033, 165)
