insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('cochituate-aqueduct-trail', 'Cochituate Aqueduct Trail', 'A dead-flat grassy path along a buried 19th-century aqueduct, running for miles through backyards and woods.', 'The aqueduct trail is Newton’s best-kept walking secret: a level, grassy corridor built over the buried brick aqueduct that once carried Lake Cochituate water to Boston. It runs for miles, crossing streets at grade and slipping behind neighborhoods.

From Waban you can walk toward Wellesley or east toward Newton Highlands. No hills, no traffic, very few people. Some sections are mown, some are rougher.', 'waban', 'outdoors-parks', 'Beacon Street near Waban Square, Waban, MA 02468', 42.3278, -71.2286, 'https://upload.wikimedia.org/wikipedia/commons/b/b7/CochituateAqueduct_WabanAvenueNewton.jpg', 'free'::price_type, 0, null, false, null, null, null, null, null, ARRAY['walking', 'flat', 'hidden gem', 'dog-friendly', 'free']::text[], true, 4.7, 121, 318, 130)
