insert into public.activities (slug, title, summary, description, village_slug, category_slug, address, lat, lng, image_url, price_type, price_min, price_max, is_event, start_at, end_at, recurrence, website, phone, tags, featured, rating_avg, rating_count, view_count, save_count) values ('west-newton-cinema', 'West Newton Cinema', 'A community-owned 1937 movie house showing indies, foreign film and matinee classics on six screens.', 'The West Newton Cinema is the kind of theatre that communities fight to keep — and Newton did, buying it collectively when it was at risk. Six screens, real butter on the popcorn, and a program that mixes new independent releases with foreign film and weekend classics.

Matinees are cheap, the seats are comfortable, and the lobby still looks like 1937 in the best way. Cash-and-card both fine; weekend evening shows sell out.', 'west-newton', 'arts-culture', '1296 Washington Street, West Newton, MA 02465', 42.3492, -71.2248, 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/West_Newton_Cinema%2C_West_Newton_MA.jpg/1920px-West_Newton_Cinema%2C_West_Newton_MA.jpg', 'paid'::price_type, 9, 16, false, null, null, 'Daily, first show around noon', 'https://westnewtoncinema.com', null, ARRAY['cinema', 'indie film', 'rainy day', 'date night', 'historic']::text[], true, 4.8, 356, 1003, 95)
